/// Expected size: 12 bytes

public enum ContractType : uint
{
    Host = 0,
    Plugin = 1,
}

///  Dispatch mechanism type — determines how function calls are routed.
public enum DispatchType : uint
{
    ///  Native dispatch: direct function pointer calls (zero overhead).
    Native = 0,
    ///  VM dispatch: call through a dispatch function with loader_data.
    VirtualMachine = 1,
}

///  How strictly version compatibility is enforced when resolving plugins.
public enum Compatibility : uint
{
    ///  Exact major match and minor >= required.
    Strict = 0,
    ///  Same major, any minor.
    Relaxed = 1,
    ///  Any version accepted.
    Yolo = 2,
}

///  Type of reload phase for FFI callbacks.
public enum ReloadPhaseType : uint
{
    ///  Bundle is being prepared for reload.
    Preparing = 0,
    ///  Bundle has been successfully reloaded.
    Reloaded = 1,
    ///  Bundle reload failed.
    Failed = 2,
    ///  Bundle is being unloaded.
    Unloading = 3,
}

///  How a bundle's loader-owned resources are handled when it is unloaded.
public enum UnloadMode : uint
{
    ///  Retire-not-drop: the loader keeps the bundle's library/VM mapped for the
    ///  runtime's lifetime after unload. Any raw function pointer already resolved
    ///  from the bundle stays valid. This is the default, fully-safe behaviour.
    Retire = 0,
    ///  Reclaim: the loader frees the bundle's library/VM at unload (e.g. native
    ///  `dlclose`), releasing OS resources and the on-disk file lock so a developer
    ///  can rebuild and reload the bundle. Host-coordinated: the host must guarantee
    ///  no thread is calling, or holds a pointer into, the bundle when it is unloaded.
    Reclaim = 1,
}

///  Runtime type identifier — identifies the language/runtime hosting plugins.
public enum RuntimeLanguage : uint
{
    Rust = 0,
    Cpp = 1,
    Dotnet = 2,
    Python = 3,
    Lua = 4,
    JavaScript = 5,
}

///  ABI error codes (reserved: 0-255 runtime, 256+ plugin-defined).
///
///  These codes are returned by all ABI functions to indicate success or failure.
///  The `code` field of `AbiError` uses these values.
public enum AbiErrorCode : uint
{
    ///  Success — no error.
    Ok = 0,
    ///  Generic error — unspecified failure.
    Generic = 1,
    ///  Buffer too small — caller must reallocate (see Buffer protocol).
    BufferTooSmall = 2,
    ///  Panic — plugin panicked (caught by catch_unwind).
    Panic = 3,
    ///  Not found — plugin/contract not found.
    NotFound = 4,
    ///  Stale handle — GuestContractHandle is invalid (contract unloaded).
    StaleHandle = 5,
    ///  Function not available — function_id >= function_count.
    FunctionNotAvailable = 6,
    ///  Duplicate provider — same bundle already provides this contract.
    DuplicateProvider = 7,
    ///  Invalid pointer — null or invalid pointer passed to ABI function.
    InvalidPointer = 8,
    ///  Reentrant call — a cross-call would re-enter a VM that is already
    ///  executing a dispatch on the same VM. Same-VM nested calls are unsupported
    ///  by the embedded interpreters (mlua, rquickjs), so the runtime rejects them
    ///  rather than risk borrow/lock conflicts inside the VM.
    ReentrantCall = 9,
    ///  Host contract not found — no host contract matches contract_id.
    HostContractNotFound = 100,
    ///  Host contract version mismatch — host contract version does not match.
    HostContractVersionMismatch = 101,
    ///  Host contract call failed — host contract function call failed.
    HostContractCallFailed = 102,
}

///  Log severity levels for the host-supplied logger callback (`RuntimeConfig::log`).
///
///  Numeric ordering is significant: lower values are more severe. A message is
///  delivered to the callback only when `level as u32 <= RuntimeConfig::log_max_level`.
public enum LogLevel : uint
{
    ///  Unrecoverable or host-visible failures (e.g. rejected registrations).
    Error = 1,
    ///  Recoverable anomalies the host should know about (e.g. lock poison recovery).
    Warn = 2,
    ///  High-level lifecycle events.
    Info = 3,
    ///  Detailed diagnostic information.
    Debug = 4,
    ///  Very fine-grained tracing.
    Trace = 5,
}

public enum ParseVersionError : uint
{
    InvalidFormat = 0,
    InvalidInt = 1,
}

///  Union of dispatch mechanisms — use based on `dispatch_type`.
///
///  # Safety
///  Access the correct variant based on `GuestContractInterface::dispatch_type`:
///  - `dispatch_type == Native` → access `.native`
///  - `dispatch_type == VirtualMachine` → access `.vm`
[StructLayout(LayoutKind.Explicit)]
public struct DispatchMechanisms
{
    [FieldOffset(0)]
    public NativeDispatch Native;
    [FieldOffset(0)]
    public VmDispatch Vm;
}


/// ABI constants for polyplug.
public static class AbiConstants
{
    public const uint POLYPLUG_ABI_VERSION = 1u;
}

// ─── Helper Methods (embedded by the build script) ───

/// <summary>
/// Helpers for constructing and converting StringViews at the ABI boundary.
/// This is the unified implementation used by both host and guest.
/// </summary>
public static class StringViewHelper
{
    /// <summary>
    /// Returns a StringView pointing at the pinned byte array via a GCHandle.
    /// Caller owns the GCHandle and must keep it alive while the StringView is in use.
    /// </summary>
    public static StringView FromPinnedHandle(GCHandle handle, int length) =>
        new StringView { Ptr = handle.AddrOfPinnedObject(), Len = (nuint)length };

    /// <summary>
    /// Returns a StringView pointing at a pre-pinned IntPtr. Caller ensures ptr validity.
    /// </summary>
    public static StringView FromPtr(IntPtr ptr, int length) =>
        new StringView { Ptr = ptr, Len = (nuint)length };

    /// <summary>
    /// Creates a StringView from a .NET string by pinning it in memory.
    /// The GCHandle must be kept alive while the StringView is in use.
    /// For guest plugins, return strings should use host allocation via registrar.
    /// </summary>
    public static (StringView View, GCHandle Handle) FromStringPinned(string str)
    {
        if (string.IsNullOrEmpty(str))
            return (new StringView { Ptr = IntPtr.Zero, Len = 0 }, default);

        byte[] bytes = Encoding.UTF8.GetBytes(str);
        GCHandle handle = GCHandle.Alloc(bytes, GCHandleType.Pinned);
        StringView sv = new StringView { Ptr = handle.AddrOfPinnedObject(), Len = (nuint)bytes.Length };
        return (sv, handle);
    }

    /// <summary>
    /// Converts a StringView to a .NET string by decoding the UTF-8 bytes
    /// directly from the native pointer (no intermediate byte[] copy).
    /// </summary>
    public static unsafe string ToString(this StringView sv)
    {
        if (sv.Ptr == IntPtr.Zero || sv.Len == 0)
            return string.Empty;

        return Encoding.UTF8.GetString((byte*)sv.Ptr, (int)sv.Len);
    }

    /// <summary>
    /// Converts a StringView to a .NET string. Alias for ToString.
    /// </summary>
    public static string ToStr(StringView sv) => ToString(sv);

    /// <summary>
    /// Checks if a StringView starts with the given prefix.
    /// </summary>
    public static bool StartsWith(StringView sv, string prefix)
    {
        if (string.IsNullOrEmpty(prefix))
            return true;
        if (sv.Ptr == IntPtr.Zero || sv.Len == 0)
            return false;

        string str = ToString(sv);
        return str.StartsWith(prefix);
    }

    /// <summary>
    /// Checks if a StringView ends with the given suffix.
    /// </summary>
    public static bool EndsWith(StringView sv, string suffix)
    {
        if (string.IsNullOrEmpty(suffix))
            return true;
        if (sv.Ptr == IntPtr.Zero || sv.Len == 0)
            return false;

        string str = ToString(sv);
        return str.EndsWith(suffix);
    }

    /// <summary>
    /// Strips the prefix from a StringView if it starts with it.
    /// Returns the original string if the prefix is not present.
    /// </summary>
    public static string StripPrefix(StringView sv, string prefix)
    {
        if (string.IsNullOrEmpty(prefix))
            return ToString(sv);

        string str = ToString(sv);
        if (str.StartsWith(prefix))
            return str.Substring(prefix.Length);
        return str;
    }

    /// <summary>
    /// Splits a StringView by the given delimiter and returns an array of strings.
    /// </summary>
    public static string[] Split(StringView sv, string delimiter)
    {
        if (sv.Ptr == IntPtr.Zero || sv.Len == 0)
            return System.Array.Empty<string>();

        string str = ToString(sv);
        if (string.IsNullOrEmpty(delimiter))
            return new[] { str };

        return str.Split(new[] { delimiter }, System.StringSplitOptions.None);
    }

    /// <summary>
    /// Returns a process-lifetime <see cref="StringView"/> for a string that
    /// crosses the ABI boundary as an <see cref="AbiError.Message"/>.
    /// </summary>
    /// <remarks>
    /// Per the ABI ownership contract, an AbiError.Message is a static or
    /// runtime-owned string that the receiver MUST NEVER free. This helper pins
    /// the UTF-8 bytes for the lifetime of the process (equivalent to .rodata),
    /// caching one buffer per distinct string so repeated errors never leak a new
    /// GCHandle. It is the only sound way to hand the host a borrowed message that
    /// nobody frees. Use it for fixed error literals — NOT for per-call argument
    /// strings (use <see cref="PinnedUtf8"/> for those).
    /// </remarks>
    public static StringView StaticMessage(string value)
    {
        if (string.IsNullOrEmpty(value))
            return new StringView { Ptr = IntPtr.Zero, Len = 0 };

        lock (s_staticMessages)
        {
            if (s_staticMessages.TryGetValue(value, out StringView cached))
                return cached;

            byte[] bytes = Encoding.UTF8.GetBytes(value);
            // Never freed: pinned for the process lifetime, mirroring .rodata.
            GCHandle handle = GCHandle.Alloc(bytes, GCHandleType.Pinned);
            StringView view = new StringView
            {
                Ptr = handle.AddrOfPinnedObject(),
                Len = (nuint)bytes.Length,
            };
            s_staticMessages[value] = view;
            return view;
        }
    }

    private static readonly System.Collections.Generic.Dictionary<string, StringView> s_staticMessages =
        new System.Collections.Generic.Dictionary<string, StringView>();
}

/// <summary>
/// Call-scoped pin of a .NET string's UTF-8 bytes, exposing a borrowed
/// <see cref="StringView"/> for passing a string ARGUMENT across the ABI
/// boundary. The argument is borrowed for the duration of the call only:
/// construct a <see cref="PinnedUtf8"/>, pass <see cref="View"/> into the call,
/// then dispose to release the pin.
/// </summary>
/// <remarks>
/// This is the correct mechanism for argument strings. It pins managed bytes
/// only for the call and frees the <see cref="GCHandle"/> on <see cref="Dispose"/>,
/// so there is no per-call leak. The host never frees this memory — it only reads
/// it for the duration of the call. For AbiError.Message values, use
/// <see cref="StringViewHelper.StaticMessage"/> instead.
/// </remarks>
public sealed class PinnedUtf8 : IDisposable
{
    private GCHandle _handle;
    private bool _pinned;

    /// <summary>
    /// The borrowed <see cref="StringView"/> over the pinned UTF-8 bytes. Valid
    /// only until <see cref="Dispose"/> is called.
    /// </summary>
    public StringView View { get; }

    public PinnedUtf8(string value)
    {
        if (string.IsNullOrEmpty(value))
        {
            View = new StringView { Ptr = IntPtr.Zero, Len = 0 };
            return;
        }

        byte[] bytes = Encoding.UTF8.GetBytes(value);
        _handle = GCHandle.Alloc(bytes, GCHandleType.Pinned);
        _pinned = true;
        View = new StringView
        {
            Ptr = _handle.AddrOfPinnedObject(),
            Len = (nuint)bytes.Length,
        };
    }

    public void Dispose()
    {
        if (_pinned)
        {
            _handle.Free();
            _pinned = false;
        }
    }
}
}
